mapper.select:
SELECT tnpr.status AS tabFlag, count(1) AS count FROM third_notice_push_record as tnpr WHERE tnpr.is_deleted=FALSE
${params.permissionSql}
GROUP BY tnpr.status

select tnpr.id as id, tnpr.create_user_id as createUserId, tnpr.create_user_name as createUserName, tnpr.create_time as createTime, tnpr.update_user_id as updateUserId, tnpr.update_user_name as updateUserName, tnpr.update_time as updateTime, tnpr.version as version, tnpr.is_deleted as isDeleted, tnpr.cfg_third_notice_id as cfgThirdNoticeId, tnpr.notice_type as noticeType, tnpr.business_id as businessId, tnpr.business_type as businessType, tnpr.business_code as businessCode, tnpr.notice_node as noticeNode, tnpr.notice_method as noticeMethod, tnpr.receiver_id as receiverId, tnpr.receiver_name as receiverName, tnpr.send_time as sendTime, tnpr.title as title, tnpr.status as status, tnpr.error_reason as errorReason from third_notice_push_record as tnpr WHERE ${params.sqlMap.default} AND tnpr.is_deleted = FALSE
and tnpr.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
tnpr.create_time DESC
